/**
 * The PDFs drawn in the browser end with the line the Worker's PDFs end with:
 * "Generated by Token Circles on 4 Nov 2026" (shared/reportFooter.ts).
 *
 * The browser wrote "Generated by Token Circles — 4 Nov 2026" and the Worker "Generated 2026-11-04"
 * (PR #695 review). The tax summary here, as cloud draws it, from a year with nothing in it; the
 * brand fonts are left out, so the PDF's text is written in Helvetica and reads as plain text.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { generateTaxSummaryPdf } from '../clientPdfReports'

vi.mock('../../apiFetch', () => ({
  apiFetch: vi.fn(async (url: string) =>
    Response.json(url.startsWith('/api/categories') ? [] : { rows: [], total: 0 })
  ),
}))

vi.mock('../../reportFonts', () => ({
  PDF_FONT: { body: 'Inter', display: 'Fraunces' },
  ensurePdfFonts: async () => false,
}))

beforeEach(() => {
  localStorage.setItem('finance_storage_mode', 'self-hosted')
  localStorage.setItem('currentProfileId', '1')
  vi.useFakeTimers({ toFake: ['Date'], now: new Date(2026, 10, 4, 12, 0) })
})

afterEach(() => {
  vi.useRealTimers()
  localStorage.clear()
})

describe('a PDF drawn in the browser', () => {
  it('ends with the day it was made, day first, as the Worker writes it', async () => {
    const pdf = new TextDecoder('latin1').decode(
      await (await generateTaxSummaryPdf(2026, false)).arrayBuffer()
    )
    expect(pdf).toContain('(Generated by Token Circles on 4 Nov 2026)')
  })
})
